package com.eduflow.service;
import com.eduflow.entity.*; import com.eduflow.exception.EduFlowException; import com.eduflow.repository.*; import com.eduflow.security.TenantRlsContext; import com.eduflow.security.CenterMembershipService; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor
public class NotificationService {
 private final CenterRepository centers; private final ParentStudentLinkRepository links; private final NotificationRepository notifications; private final CenterMembershipService memberships; private final TenantRlsContext tenantRls;
 @Transactional public void notifyStudentParents(Long centerId,Long studentId,String type,String title,String message){apply(centerId);for(ParentStudentLink link:links.findAllByCenter_IdAndStudent_IdAndActiveTrue(centerId,studentId)){try{memberships.assertRoleForUserId(link.getParent().getId(),centerId,Role.PARENT);if(link.getParent().isEnabled()&&link.getParent().getStatus()==UserStatus.ACTIVE)notifications.save(new Notification(link.getCenter(),link.getParent(),type,title,message));}catch(org.springframework.security.access.AccessDeniedException ignored){/* Suspended or changed parent membership receives no new notifications. */}}}
 @Transactional(readOnly=true) public List<Notification> list(Long centerId,Long userId){apply(centerId);return notifications.findTop100ByCenter_IdAndRecipient_IdOrderByCreatedAtDesc(centerId,userId);}
 @Transactional public Notification markRead(Long centerId,Long userId,Long notificationId){apply(centerId);Notification n=notifications.findByIdAndCenter_IdAndRecipient_Id(notificationId,centerId,userId).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"notification.not-found"));if(n.getReadAt()==null)n.setReadAt(Instant.now());return n;}
 private void apply(Long id){if(id==null)throw new EduFlowException(HttpStatus.BAD_REQUEST,"tenant.context.required");tenantRls.apply(id);Center c=centers.findById(id).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"center.not-found"));if(c.getStatus()!=CenterStatus.ACTIVE)throw new EduFlowException(HttpStatus.FORBIDDEN,"tenant.center.inactive");}
}
